def blend_equal(signals):
    """Equal-weight vote across strategy signal frames.

    Parameters
    ----------
    signals : list of pd.DataFrame
        Each with ``signal``/``confidence``/``gate`` columns.

    Returns
    -------
    pd.DataFrame with ``vote``, ``agreement`` and ``n`` columns.
    """
    if not signals:
        return pd.DataFrame(columns=["vote", "agreement", "n"])
    idx = signals[0].index
    votes = np.zeros(len(idx))
    conf_sum = np.zeros(len(idx))
    for s in signals:
        w = (s["confidence"].to_numpy(dtype=float) * s["gate"].to_numpy(dtype=float))
        votes = votes + np.sign(s["signal"].to_numpy(dtype=float)) * w
        conf_sum = conf_sum + w
    vote = votes / (conf_sum + 1e-12)
    n = float(len(signals))
    pos = np.zeros(len(idx))
    for s in signals:
        pos = pos + (np.sign(s["signal"].to_numpy(dtype=float)) > 0).astype(float)
    agreement = np.abs(pos / n - 0.5) * 2.0
    return pd.DataFrame({"vote": vote, "agreement": agreement, "n": n}, index=idx)


def blend_topk(signals, names, scores, k=12):
    """Blend only the top-k strategies by ``scores`` mapping."""
    if not signals:
        return blend_equal(signals)
    order = sorted(range(len(signals)), key=lambda i: scores.get(names[i], 0.0), reverse=True)
    picks = [signals[i] for i in order[: max(1, min(k, len(signals)))]]
    return blend_equal(picks)


def hysteresis_filter(vote, threshold=0.15, release=0.05):
    """Schmitt-trigger filter that stops flip-flopping inside noise."""
    v = np.asarray(vote, dtype=float)
    out = np.zeros(len(v))
    state = 0.0
    for i in range(len(v)):
        if state == 0.0 and abs(v[i]) > threshold:
            state = float(np.sign(v[i]))
        elif state != 0.0 and (np.sign(v[i]) != np.sign(state) and abs(v[i]) > threshold):
            state = float(np.sign(v[i]))
        elif state != 0.0 and abs(v[i]) < release:
            state = 0.0
        out[i] = state
    try:
        idx = vote.index
    except Exception:
        idx = None
    return pd.Series(out, index=idx, name="position")


def confluence_report(blend, price=None):
    """Summarize a blend frame into bias/strength/participation stats."""
    vote = blend["vote"].to_numpy(dtype=float)
    out = {
        "bias": float(vote[-1]) if len(vote) else 0.0,
        "mean_abs_vote": float(np.mean(np.abs(vote))) if len(vote) else 0.0,
        "agreement": float(blend["agreement"].iloc[-1]) if len(blend) else 0.0,
        "n": float(blend["n"].iloc[-1]) if len(blend) else 0.0,
        "long_frac": float(np.mean(vote > 0.1)) if len(vote) else 0.0,
        "short_frac": float(np.mean(vote < -0.1)) if len(vote) else 0.0,
    }
    if price is not None:
        px = np.asarray(price, dtype=float)
        if len(px) == len(vote) and len(px) > 2:
            out["vote_price_corr"] = float(np.corrcoef(vote, px)[0, 1])
    return out

